import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class MemberTest {

    @Test
    void donor_member_can_borrow_beyond_the_limit() {
        Member donor = Member.reconstitute(UUID.fromString("11111111-1111-1111-1111-111111111111"), "후원자");

        assertThatCode(() -> donor.ensureCanBorrow(Member.MAX_ACTIVE_LOANS))
                .doesNotThrowAnyException();
    }

    @Test
    void suspended_member_cannot_borrow() {
        Member member = Member.register(UUID.randomUUID(), "김민지");
        member.suspend();

        assertThatThrownBy(() -> member.ensureCanBorrow(0))
                .isInstanceOf(MemberSuspendedException.class);
    }

    @Test
    void suspended_donor_member_cannot_borrow() {
        Member donor = Member.reconstitute(UUID.fromString("11111111-1111-1111-1111-111111111111"), "후원자", true);

        assertThatThrownBy(() -> donor.ensureCanBorrow(0))
                .isInstanceOf(MemberSuspendedException.class);
    }

    @Test
    void unsuspended_member_can_borrow_again() {
        Member member = Member.register(UUID.randomUUID(), "김민지");
        member.suspend();
        member.unsuspend();

        assertThatCode(() -> member.ensureCanBorrow(0))
                .doesNotThrowAnyException();
    }
}

